package com.funnywork;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Clock;
import java.util.*;

/** Immutable instruction-only skills. No executable, file path or credential is distributed. */
@Service
public class PublishedSkills {
 public record Publish(@NotBlank @Pattern(regexp="[a-z0-9][a-z0-9.-]{0,119}") String name,@NotBlank @Pattern(regexp="[0-9]+\\.[0-9]+\\.[0-9]+") @Size(max=40) String version,@NotBlank @Pattern(regexp="[a-z0-9-]{1,64}") String zone,@NotBlank @Size(max=12000) String instructions){}
 private final JdbcTemplate db;private final AuthService auth;private final TenantLocks locks;private final Clock clock;private final ControlService control;
 public PublishedSkills(JdbcTemplate db,AuthService auth,TenantLocks locks,Clock clock,ControlService control){this.db=db;this.auth=auth;this.locks=locks;this.clock=clock;this.control=control;}
 @Transactional public Map<String,Object> publish(Identity actor,Publish body){locks.lock(actor.tenant());actor=auth.current(actor);actor.requireUser("ADMIN");actor.requireZone(body.zone());if(body.instructions().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>8000)throw new ApiException(413,"SKILL_TOO_LARGE","Skill exceeds 8000 UTF-8 bytes");String id=AuthService.id(),hash=AuthService.hash(body.instructions());db.update("insert into published_skills values(?,?,?,?,?,?,?,true,?)",id,actor.tenant(),body.zone(),body.name(),body.version(),body.instructions(),hash,clock.millis());auth.audit(actor,"SKILL_PUBLISHED",Map.of("skillId",id,"sha256",hash));return Map.of("id",id,"sha256",hash);}
 @Transactional(readOnly=true) public Map<String,Object> list(Identity actor,String zone,String after,int limit){actor=auth.current(actor);actor.requireUser("ADMIN");actor.requireZone(zone);if(after==null || after.length()>64 || limit<1 || limit>100)throw new ApiException(400,"INVALID_PAGE","Invalid page");var rows=db.queryForList("select id,name,version,zone,content_hash,enabled,created_at from published_skills where tenant_id=? and zone=? and id>? order by id limit ?",actor.tenant(),zone,after,limit+1);boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);var result=new LinkedHashMap<String,Object>();result.put("items",rows);if(more)result.put("nextCursor",rows.get(rows.size()-1).get("id"));return result;}
 private Map<String,Object> skill(Identity actor,String id){actor=auth.current(actor);actor.requireUser("ADMIN");var rows=db.queryForList("select * from published_skills where id=? and tenant_id=?",id,actor.tenant());if(rows.isEmpty())throw ApiException.missing();actor.requireZone((String)rows.get(0).get("zone"));return rows.get(0);}
 @Transactional public void disable(Identity actor,String id){locks.lock(actor.tenant());skill(actor,id);db.update("update published_skills set enabled=false where id=? and tenant_id=?",id,actor.tenant());auth.audit(auth.current(actor),"SKILL_DISABLED",Map.of("skillId",id));}
 @Transactional public void bind(Identity actor,String agentId,String skillId,boolean enabled){locks.lock(actor.tenant());var s=skill(actor,skillId);var agents=db.queryForList("select capability from agent_versions where id=? and tenant_id=? and status='PUBLISHED'",agentId,actor.tenant());if(agents.isEmpty())throw ApiException.missing();if(!"model.read.v1".equals(agents.get(0).get("capability")))throw ApiException.forbidden();
  if(enabled){if(!Boolean.TRUE.equals(s.get("enabled")))throw ApiException.forbidden();if(db.queryForObject("select count(*) from agent_skill_defaults where tenant_id=? and agent_id=? and skill_id=?",Integer.class,actor.tenant(),agentId,skillId)==0){int count=db.queryForObject("select count(*) from agent_skill_defaults d join published_skills s on s.id=d.skill_id where d.tenant_id=? and d.agent_id=? and s.zone=?",Integer.class,actor.tenant(),agentId,s.get("zone"));if(count>=4)throw new ApiException(429,"SKILL_LIMIT","At most four skills per agent and zone");db.update("insert into agent_skill_defaults values(?,?,?)",actor.tenant(),agentId,skillId);}}
  else db.update("delete from agent_skill_defaults where tenant_id=? and agent_id=? and skill_id=?",actor.tenant(),agentId,skillId);auth.audit(auth.current(actor),enabled?"AGENT_SKILL_BOUND":"AGENT_SKILL_UNBOUND",Map.of("agentId",agentId,"skillId",skillId));
 }
 @Transactional(readOnly=true) public List<Map<String,Object>> defaults(Identity actor,String agent,String zone){actor=auth.current(actor);actor.requireUser("ADMIN");actor.requireZone(zone);if(db.queryForList("select id from agent_versions where tenant_id=? and id=?",actor.tenant(),agent).isEmpty())throw ApiException.missing();return db.queryForList("select s.id,s.name,s.version,s.enabled from agent_skill_defaults d join published_skills s on s.id=d.skill_id where d.tenant_id=? and d.agent_id=? and s.zone=? order by s.id",actor.tenant(),agent,zone);}
 @Transactional public List<Map<String,Object>> forAttempt(Identity node,String attempt,long epoch){locks.lock(node.tenant());var lease=control.modelLease(node,attempt,epoch,false);var rows=db.queryForList("select s.id,s.name,s.version,s.instructions,s.content_hash from task_skills t join published_skills s on s.id=t.skill_id where t.task_id=? and t.tenant_id=? and s.tenant_id=? and s.enabled=true order by s.id limit 5",lease.taskId(),node.tenant(),node.tenant());if(rows.size()>4)throw new ApiException(413,"SKILL_LIMIT","Skill input budget exceeded");return rows;}
}
